@Suppress("UnstableApiUsage")
testing.suites.named<JvmTestSuite>("test") {
    useJUnitJupiter()
}

@OptIn(org.jetbrains.kotlin.gradle.ExperimentalKotlinGradlePluginApi::class)
powerAssert {
    functions.set(
        listOf(
            "kotlin.assert",
            "kotlin.require",
            "kotlin.requireNotNull",
            "kotlin.check",
            "kotlin.checkNotNull",
            "kotlin.test.assertTrue",
            "kotlin.test.assertFalse",
            "kotlin.test.assertEquals",
            "kotlin.test.assertNull",
            "opensavvy.prepared.suite.assertions.log",
        )
    )
}

/**
 * Automatically adds the KotlinX.Coroutines Debug Agent to JVM tests.
 *
 * Disable with -PcoroutinesDebugAgent=false
 */
if ((findProperty("coroutinesDebugAgent") as? String)?.toBoolean() != false) {
    val coroutinesDebugAgent = configurations.detachedConfiguration(
        dependencies.create(libs.kotlinx.coroutines.debug.get())
    ).apply {
        isTransitive = false
    }

    tasks.withType<Test>().configureEach {
        val agentJar = files(coroutinesDebugAgent)
        inputs.files(agentJar).withPropertyName("coroutinesDebugAgent").withNormalizer(ClasspathNormalizer::class)
        jvmArgumentProviders.add(CommandLineArgumentProvider { listOf("-javaagent:${agentJar.singleFile.absolutePath}") })

        systemProperty("kotlinx.coroutines.debug.enable.creation.stack.trace", "true")
    }
}

// endregion
